import {load,act} from './store.js';
import {handleMcp} from './mcp.js';
import page from './index.html';
import {fresh,view,choose,VERSION} from './engine.js';
const json=(v,status=200)=>Response.json(v,{status,headers:{'Cache-Control':'no-store'}});
export default {async fetch(req,env){const url=new URL(req.url);if(url.pathname==='/mcp')return handleMcp(req,env);if(url.pathname==='/')return new Response(page,{headers:{'Content-Type':'text/html;charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff','Content-Security-Policy':"default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; object-src 'none'; base-uri 'none'"}});if(!url.pathname.startsWith('/api/'))return new Response('Not found',{status:404});const user=req.headers.get('oai-authenticated-user-id');if(!user)return json({error:'请用 ChatGPT 账号登录后继续'},401);if(req.method!=='GET'&&req.headers.get('Origin')!==url.origin)return json({error:'不允许跨站提交'},403);try{if(!env.DB)throw Error('Save storage unavailable');if(url.pathname==='/api/archives'&&req.method==='GET'){const result=await env.DB.prepare('SELECT payload,created_at FROM archives WHERE user_id=? ORDER BY created_at DESC LIMIT 10').bind(user).all();return json({archives:result.results.map(r=>{const s=JSON.parse(r.payload);return {version:s.version,date:r.created_at,history:s.history,scene:s.scene};})});}if(url.pathname==='/api/state'&&req.method==='GET')return json(view(await load(env.DB,user)));if(req.method!=='POST')return json({error:'请求方式不支持'},405);const body=await req.json();if(!['/api/choose','/api/restart','/api/sequel'].includes(url.pathname))return json({error:'没有这个操作'},404);try{return json(view(await act(env.DB,user,body,url.pathname==='/api/restart'?'restart':url.pathname==='/api/sequel'?'sequel':'choose')));}catch(e){return json({error:e.message,...(e.state?{state:view(e.state)}:{})},e.status||400);}}catch(e){console.error('game request failed',e);return json({error:'暂时无法读取或保存进度。请稍后重试；未确认的操作不会在界面中前进。'},503);}}};
